const mri = require('./lib/index.js');

let passed = 0;
let failed = 0;

function test(description, fn) {
    try {
        fn();
        passed++;
        console.log(`✓ ${description}`);
    } catch (e) {
        failed++;
        console.log(`✗ ${description}`);
        console.log(`  Error: ${e.message}`);
    }
}

function assert(condition, message) {
    if (!condition) {
        throw new Error(message || 'Assertion failed');
    }
}

function deepEqual(a, b) {
    return JSON.stringify(a) === JSON.stringify(b);
}

// Original issue tests
test('boolean default with boolean flag - _ should be empty', () => {
    const result = mri(['--foo'], { boolean: 'foo', default: { bar: false } });
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
    assert(result.foo === true, `Expected foo to be true, got ${result.foo}`);
    assert(result.bar === false, `Expected bar to be false, got ${result.bar}`);
});

test('boolean default 0 with boolean flag - _ should be empty', () => {
    const result = mri(['--foo'], { boolean: 'foo', default: { bar: 0 } });
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
    assert(result.foo === true, `Expected foo to be true, got ${result.foo}`);
    assert(result.bar === 0, `Expected bar to be 0, got ${result.bar}`);
});

test('multiple boolean defaults - _ should be empty', () => {
    const result = mri(['--verbose'], { boolean: 'verbose', default: { json: false, color: true } });
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
    assert(result.verbose === true, `Expected verbose to be true, got ${result.verbose}`);
    assert(result.json === false, `Expected json to be false, got ${result.json}`);
    assert(result.color === true, `Expected color to be true, got ${result.color}`);
});

// Edge cases for boolean handling
test('boolean flag with string "true" value', () => {
    const result = mri(['--foo', 'true'], { boolean: 'foo' });
    assert(result.foo === true, `Expected foo to be true, got ${result.foo}`);
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
});

test('boolean flag with string "false" value', () => {
    const result = mri(['--foo', 'false'], { boolean: 'foo' });
    assert(result.foo === false, `Expected foo to be false, got ${result.foo}`);
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
});

test('boolean flag with numeric value 1 should push to _', () => {
    const result = mri(['--foo', '1'], { boolean: 'foo' });
    assert(result.foo === true, `Expected foo to be true, got ${result.foo}`);
    assert(result._.length === 1, `Expected _ to have 1 element, got ${JSON.stringify(result._)}`);
    assert(result._[0] === 1, `Expected _[0] to be 1, got ${result._[0]}`);
});

test('boolean flag with numeric value 0 should push to _', () => {
    const result = mri(['--foo', '0'], { boolean: 'foo' });
    assert(result.foo === true, `Expected foo to be true, got ${result.foo}`);
    assert(result._.length === 1, `Expected _ to have 1 element, got ${JSON.stringify(result._)}`);
    assert(result._[0] === 0, `Expected _[0] to be 0, got ${result._[0]}`);
});

// Tests without boolean option in opts
test('boolean default without boolean option - should not affect _', () => {
    const result = mri(['--foo', 'bar'], { default: { baz: false } });
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
    assert(result.foo === 'bar', `Expected foo to be 'bar', got ${result.foo}`);
    assert(result.baz === false, `Expected baz to be false, got ${result.baz}`);
});

test('positional args with boolean defaults should work', () => {
    const result = mri(['positional'], { default: { flag: false } });
    assert(result._.length === 1, `Expected _ to have 1 element, got ${JSON.stringify(result._)}`);
    assert(result._[0] === 'positional', `Expected _[0] to be 'positional', got ${result._[0]}`);
    assert(result.flag === false, `Expected flag to be false, got ${result.flag}`);
});

// String option tests
test('string option should not be affected by defaults', () => {
    const result = mri(['-s', '0001234'], { string: 's', default: { flag: false } });
    assert(result.s === '0001234', `Expected s to be '0001234', got ${result.s}`);
    assert(result.flag === false, `Expected flag to be false, got ${result.flag}`);
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
});

// Boolean with no value
test('boolean flag alone should be true', () => {
    const result = mri(['--verbose'], { boolean: 'verbose' });
    assert(result.verbose === true, `Expected verbose to be true, got ${result.verbose}`);
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
});

// Short boolean flag
test('short boolean flag should work', () => {
    const result = mri(['-v'], { boolean: 'v' });
    assert(result.v === true, `Expected v to be true, got ${result.v}`);
    assert(result._.length === 0, `Expected _ to be empty, got ${JSON.stringify(result._)}`);
});

console.log(`\n${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

